#include <vector>
#include <algorithm>

class Solution {
public:
    int findLengthOfShortestSubarray(std::vector<int>& arr) {
        int n = arr.size();
        int left = 0;
        while (left + 1 < n && arr[left] <= arr[left + 1]) left++;
        if (left == n - 1) return 0;
        int right = n - 1;
        while (right > 0 && arr[right - 1] <= arr[right]) right--;
        int ans = std::min(n - 1 - left, right);
        int i = 0, j = right;
        while (i <= left && j < n) {
            if (arr[i] <= arr[j]) {
                ans = std::min(ans, j - i - 1);
                i++;
            } else {
                j++;
            }
        }
        return ans;
    }
};

class Solution {
    public int findLengthOfShortestSubarray(int[] arr) {
        int n = arr.length;
        int left = 0;
        while (left + 1 < n && arr[left] <= arr[left + 1]) left++;
        if (left == n - 1) return 0;
        int right = n - 1;
        while (right > 0 && arr[right - 1] <= arr[right]) right--;
        int ans = Math.min(n - 1 - left, right);
        int i = 0, j = right;
        while (i <= left && j < n) {
            if (arr[i] <= arr[j]) {
                ans = Math.min(ans, j - i - 1);
                i++;
            } else {
                j++;
            }
        }
        return ans;
    }
}

var findLengthOfShortestSubarray = function(arr) {
    const n = arr.length;
    let left = 0;
    while (left + 1 < n && arr[left] <= arr[left + 1]) left++;
    if (left === n - 1) return 0;
    let right = n - 1;
    while (right > 0 && arr[right - 1] <= arr[right]) right--;
    let ans = Math.min(n - 1 - left, right);
    let i = 0, j = right;
    while (i <= left && j < n) {
        if (arr[i] <= arr[j]) {
            ans = Math.min(ans, j - i - 1);
            i++;
        } else {
            j++;
